import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor weight,
                                            c10::optional<torch::Tensor> bias,
                                            int64_t stride,
                                            int64_t padding,
                                            int64_t output_padding,
                                            int64_t dilation,
                                            int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------------
// Pipelined staged loads: double-buffered cp.async staging of the per-chunk
// input halo and weight slab, so global-memory latency for the next
// input-channel chunk overlaps the current chunk's compute.
namespace convt3d_pipe_cfg {
constexpr int TILE_Z   = 4;
constexpr int TILE_Y   = 4;
constexpr int TILE_X   = 16;
constexpr int K3       = 3;
constexpr int IN_Z     = TILE_Z + K3 - 1;
constexpr int IN_Y     = TILE_Y + K3 - 1;
constexpr int IN_X     = TILE_X + K3 - 1;
constexpr int CO_TILE  = 24;
constexpr int CI_CHUNK = 4;
constexpr int THREADS  = 256;
constexpr int SX_PAD_X = IN_X + 1;
constexpr int SX_ELEMS = CI_CHUNK * IN_Z * IN_Y * SX_PAD_X;
constexpr int SX_LOGICAL_ELEMS = CI_CHUNK * IN_Z * IN_Y * IN_X;
constexpr int SW_ELEMS = CI_CHUNK * CO_TILE * K3 * K3 * K3;
}  // namespace convt3d_pipe_cfg
// 4-byte cp.async with zero-fill for out-of-bounds elements (sm_80+).
__device__ __forceinline__ void cp_async4_zfill(void* smem_dst, const void* gmem_src, bool valid) {
  const unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
  const int src_size = valid ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" :: "r"(dst), "l"(gmem_src), "r"(src_size));
}
__device__ __forceinline__ void cp_async_commit() {
  asm volatile("cp.async.commit_group;\n" ::);
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}
// Issue all global->shared async copies for one input-channel chunk.
// Out-of-range halo / channel / output-channel elements are zero-filled in
// shared memory via the cp.async src-size operand (same semantics as the
// previous synchronous loader's T(0) fill).
template <typename T>
__device__ __forceinline__ void convt3d_stage_chunk_async(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ sXb,
    T* __restrict__ sWb,
    int n, int C, int Din, int Hin, int Win, int OC,
    int ci0, int iz0, int iy0, int ix0, int co_base, int tid)
{
  using namespace convt3d_pipe_cfg;
  static_assert(sizeof(T) == 4, "cp.async 4-byte staging requires 32-bit elements");
  for (int e = tid; e < SX_LOGICAL_ELEMS; e += THREADS) {
    const int cil = e / (IN_Z * IN_Y * IN_X);
    const int rem = e - cil * (IN_Z * IN_Y * IN_X);
    const int liz = rem / (IN_Y * IN_X);
    const int rem2 = rem - liz * (IN_Y * IN_X);
    const int liy = rem2 / IN_X;
    const int lix = rem2 - liy * IN_X;
    const int ci = ci0 + cil;
    const int gz = iz0 + liz;
    const int gy = iy0 + liy;
    const int gx = ix0 + lix;
    const bool valid = (ci < C) &&
                       (unsigned)gz < (unsigned)Din &&
                       (unsigned)gy < (unsigned)Hin &&
                       (unsigned)gx < (unsigned)Win;
    const T* src = X;
    if (valid) {
      int64_t off = gx;
      off += (int64_t)gy * Win;
      off += (int64_t)gz * Hin * Win;
      off += (int64_t)ci * Din * Hin * Win;
      off += (int64_t)n * C * Din * Hin * Win;
      src = X + off;
    }
    T* dst = sXb + (cil * (IN_Z * IN_Y * SX_PAD_X) +
                    liz * (IN_Y * SX_PAD_X) +
                    liy * SX_PAD_X + lix);
    cp_async4_zfill(dst, src, valid);
  }
  for (int e = tid; e < SW_ELEMS; e += THREADS) {
    const int cil = e / (CO_TILE * K3 * K3 * K3);
    const int rem = e - cil * (CO_TILE * K3 * K3 * K3);
    const int co_local = rem / (K3 * K3 * K3);
    const int k = rem - co_local * (K3 * K3 * K3);
    const int ci = ci0 + cil;
    const int co = co_base + co_local;
    const bool valid = (ci < C) && (co < OC);
    const T* src = W;
    if (valid) {
      src = W + (((int64_t)ci * OC + co) * (K3 * K3 * K3) + k);
    }
    T* dst = sWb + (cil * (CO_TILE * K3 * K3 * K3) + co_local * (K3 * K3 * K3) + k);
    cp_async4_zfill(dst, src, valid);
  }
}
// Specialized fast path for the requested module:
// ConvTranspose3d, groups=1, stride=1, dilation=1, output_padding=0, k=3.
// With stride=1 this is an output-stationary direct form:
//   y[o] = sum_ci sum_{kz,ky,kx} x[o + padding - k] * W[ci, co, k]
// The CTA cooperatively tiles a 4x4x16 output brick and stages the needed
// 6x6x18 input halo for a chunk of input channels in shared memory.
template <typename T, int K>
__global__ void convt3d_s1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int Din, int Hin, int Win,
    int OC, int Dout, int Hout, int Wout,
    int padding)
{
  constexpr int TILE_Z   = 4;
  constexpr int TILE_Y   = 4;
  constexpr int TILE_X   = 16;   // keep CTA brick; widen per-thread x register blocking instead
  constexpr int K3       = 3;
  constexpr int IN_Z     = TILE_Z + K3 - 1;   // 6
  constexpr int IN_Y     = TILE_Y + K3 - 1;   // 6
  constexpr int IN_X     = TILE_X + K3 - 1;   // 18
  constexpr int CO_TILE  = 24;
  constexpr int CI_CHUNK = 4;   // halved so two pipeline stages fit the same shared budget
  constexpr int THREADS  = 256;
  constexpr int NSP      = 8;   // eight x-adjacent output voxels per thread (deeper register blocking)
  constexpr int X_SLOTS  = TILE_X / NSP;      // 2
  constexpr int SLOTS    = TILE_Z * TILE_Y * X_SLOTS; // 32
  constexpr int NACC     = CO_TILE / (THREADS / SLOTS); // 24 / 8 = 3
  constexpr int SX_PAD_X  = IN_X + 1;                            // pad smem halo x-stride to reduce bank conflicts
  constexpr int SX_ELEMS = CI_CHUNK * IN_Z * IN_Y * SX_PAD_X;    // padded shared storage
  constexpr int SX_LOGICAL_ELEMS = CI_CHUNK * IN_Z * IN_Y * IN_X; // logical halo elements loaded
  constexpr int SW_ELEMS = CI_CHUNK * CO_TILE * K3 * K3 * K3;         // 5184
  static_assert(K == 3, "This kernel is specialized for kernel_size=3");
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int co_tile = blockIdx.y;
  const int tiles_w = (Wout + TILE_X - 1) / TILE_X;
  const int tiles_h = (Hout + TILE_Y - 1) / TILE_Y;
  const int bx = blockIdx.x;
  const int tx = bx % tiles_w;
  const int rem0 = bx / tiles_w;
  const int ty = rem0 % tiles_h;
  const int tz = rem0 / tiles_h;
  const int oz0 = tz * TILE_Z;
  const int oy0 = ty * TILE_Y;
  const int ox0 = tx * TILE_X;
  // Global tensors in CUTE.
  const int64_t sXn = (int64_t)C * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)OC * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sWci = (int64_t)OC * K3 * K3 * K3;
  Tensor mX = make_tensor(make_gmem_ptr(X),
                          make_shape(N, C, Din, Hin, Win),
                          make_stride(sXn, sXc, sXd, sXh, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(N, OC, Dout, Hout, Wout),
                          make_stride(sYn, sYc, sYd, sYh, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(W),
                          make_shape(C, OC, Int<K3>{}, Int<K3>{}, Int<K3>{}),
                          make_stride(sWci, (int64_t)K3*K3*K3, (int64_t)K3*K3, (int64_t)K3, Int<1>{}));
  // Double-buffered shared input halo: (ci_chunk, z, y, x), x fastest.
  __shared__ T sX_raw[2 * SX_ELEMS];
  // Double-buffered shared weight tile: (ci_chunk, co_tile, kz, ky, kx), kx fastest.
  __shared__ T sW_raw[2 * SW_ELEMS];
  // Thread mapping: each thread owns four x-adjacent points of the 4x4x16 brick
  // (64 spatial slots) and one of four 6-channel groups. Keeping 24 accumulators
  // per thread while doubling NSP halves shared-weight loads per output voxel,
  // improving smem reuse for the k=3 stencil without changing launch tiling.
  const int s_slot = tid & 31;
  const int oz = s_slot >> 3;
  const int oy = (s_slot >> 1) & 3;
  const int ox = (s_slot & 1) * NSP;
  const int cg = tid >> 5; // 0..7
  const int ozg = oz0 + oz;
  const int oyg = oy0 + oy;
  const int oxg0 = ox0 + ox;
  const int oxg1 = oxg0 + 1;
  const int oxg2 = oxg0 + 2;
  const int oxg3 = oxg0 + 3;
  const int oxg4 = oxg0 + 4;
  const int oxg5 = oxg0 + 5;
  const int oxg6 = oxg0 + 6;
  const int oxg7 = oxg0 + 7;
  int co_a[NACC];
  int co_l[NACC];
  bool co_valid[NACC];
  float acc0[NACC], acc1[NACC], acc2[NACC], acc3[NACC], acc4[NACC], acc5[NACC], acc6[NACC], acc7[NACC];
  // NSP x NACC register tile remains 24 accumulators per thread.
  #pragma unroll
  for (int a = 0; a < NACC; ++a) {
    // +8 comes from 256 threads / 32 spatial slots; striding covers all 24 output channels.
    int co_local = cg + 8 * a;
    int co = co_tile * CO_TILE + co_local;
    co_l[a] = co_local;
    co_a[a] = co;
    co_valid[a] = (co_local < CO_TILE) && (co < OC);
    float b0 = 0.0f;
    if (B != nullptr && co_valid[a]) {
      b0 = (float)B[co];
    }
    acc0[a] = b0; acc1[a] = b0;
    acc2[a] = b0; acc3[a] = b0;
    acc4[a] = b0; acc5[a] = b0;
    acc6[a] = b0; acc7[a] = b0;
  }
  // Input halo origin for this output brick.
  const int iz0 = oz0 + padding - (K3 - 1);
  const int iy0 = oy0 + padding - (K3 - 1);
  const int ix0 = ox0 + padding - (K3 - 1);
  const int nchunks = (C + CI_CHUNK - 1) / CI_CHUNK;
  const int co_base = co_tile * CO_TILE;
  // Software pipeline over input-channel chunks (double-buffered cp.async):
  // stage chunk 0, then prefetch chunk c+1 while computing chunk c.
  convt3d_stage_chunk_async<T>(X, W, sX_raw, sW_raw,
                               n, C, Din, Hin, Win, OC,
                               0, iz0, iy0, ix0, co_base, tid);
  cp_async_commit();
  for (int c = 0; c < nchunks; ++c) {
    const int buf = c & 1;
    const int ci0 = c * CI_CHUNK;
    if (c + 1 < nchunks) {
      convt3d_stage_chunk_async<T>(X, W,
                                   sX_raw + ((c + 1) & 1) * SX_ELEMS,
                                   sW_raw + ((c + 1) & 1) * SW_ELEMS,
                                   n, C, Din, Hin, Win, OC,
                                   ci0 + CI_CHUNK, iz0, iy0, ix0, co_base, tid);
      cp_async_commit();
      cp_async_wait_group<1>(); // current chunk's group landed; next still in flight
    } else {
      cp_async_wait_group<0>();
    }
    __syncthreads();
    Tensor sX = make_tensor(make_smem_ptr(sX_raw + buf * SX_ELEMS),
                            make_shape(Int<CI_CHUNK>{}, Int<IN_Z>{}, Int<IN_Y>{}, Int<IN_X>{}),
                            make_stride(Int<IN_Z*IN_Y*SX_PAD_X>{},
                                        Int<IN_Y*SX_PAD_X>{},
                                        Int<SX_PAD_X>{},
                                        Int<1>{}));
    Tensor sW = make_tensor(make_smem_ptr(sW_raw + buf * SW_ELEMS),
                            make_shape(Int<CI_CHUNK>{}, Int<CO_TILE>{}, Int<K3>{}, Int<K3>{}, Int<K3>{}),
                            make_stride(Int<CO_TILE*K3*K3*K3>{},
                                        Int<K3*K3*K3>{},
                                        Int<K3*K3>{},
                                        Int<K3>{},
                                        Int<1>{}));
    if ((ozg < Dout) && (oyg < Hout) && (oxg0 < Wout)) {
      const int ci_lim = min(CI_CHUNK, C - ci0);
      #pragma unroll
      for (int cil = 0; cil < CI_CHUNK; ++cil) {
        if (cil >= ci_lim) break;
        #pragma unroll
        for (int kz = 0; kz < K3; ++kz) {
          const int liz = oz + (K3 - 1) - kz;
          #pragma unroll
          for (int ky = 0; ky < K3; ++ky) {
            const int liy = oy + (K3 - 1) - ky;
            // Stage the K3+NSP-1 consecutive halo x-values once per (cil, kz, ky);
            // the four register-blocked output points consume shifted 3-tap windows.
            float xs[K3 + NSP - 1];
            #pragma unroll
            for (int i = 0; i < K3 + NSP - 1; ++i) {
              xs[i] = (float)sX(cil, liz, liy, ox + i);
            }
            #pragma unroll
            for (int kx = 0; kx < K3; ++kx) {
              const float xv0 = xs[(K3 - 1) - kx];
              const float xv1 = xs[(K3 - 1) - kx + 1];
              const float xv2 = xs[(K3 - 1) - kx + 2];
              const float xv3 = xs[(K3 - 1) - kx + 3];
              const float xv4 = xs[(K3 - 1) - kx + 4];
              const float xv5 = xs[(K3 - 1) - kx + 5];
              const float xv6 = xs[(K3 - 1) - kx + 6];
              const float xv7 = xs[(K3 - 1) - kx + 7];
              #pragma unroll
              for (int a = 0; a < NACC; ++a) {
                if (co_valid[a]) {
                  const float wv = (float)sW(cil, co_l[a], kz, ky, kx);
                  acc0[a] = fmaf(xv0, wv, acc0[a]); acc1[a] = fmaf(xv1, wv, acc1[a]);
                  acc2[a] = fmaf(xv2, wv, acc2[a]); acc3[a] = fmaf(xv3, wv, acc3[a]);
                  acc4[a] = fmaf(xv4, wv, acc4[a]); acc5[a] = fmaf(xv5, wv, acc5[a]);
                  acc6[a] = fmaf(xv6, wv, acc6[a]); acc7[a] = fmaf(xv7, wv, acc7[a]);
                }
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int a = 0; a < NACC; ++a) {
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg0 < Wout) mY(n, co_a[a], ozg, oyg, oxg0) = (T)acc0[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg1 < Wout) mY(n, co_a[a], ozg, oyg, oxg1) = (T)acc1[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg2 < Wout) mY(n, co_a[a], ozg, oyg, oxg2) = (T)acc2[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg3 < Wout) mY(n, co_a[a], ozg, oyg, oxg3) = (T)acc3[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg4 < Wout) mY(n, co_a[a], ozg, oyg, oxg4) = (T)acc4[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg5 < Wout) mY(n, co_a[a], ozg, oyg, oxg5) = (T)acc5[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg6 < Wout) mY(n, co_a[a], ozg, oyg, oxg6) = (T)acc6[a];
    if (co_valid[a] && ozg < Dout && oyg < Hout && oxg7 < Wout) mY(n, co_a[a], ozg, oyg, oxg7) = (T)acc7[a];
  }
  // Store the widened 4-point x register tile.
  // Launch tiling (TILE_X=16, 256 threads) is unchanged.
}

torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor weight,
                                            c10::optional<torch::Tensor> bias,
                                            int64_t stride,
                                            int64_t padding,
                                            int64_t output_padding,
                                            int64_t dilation,
                                            int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA when provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout, kD, kH, kW]");

  TORCH_CHECK(groups == 1, "custom CUTE kernel currently supports groups=1");
  TORCH_CHECK(stride == 1, "custom CUTE kernel currently supports stride=1");
  TORCH_CHECK(dilation == 1, "custom CUTE kernel currently supports dilation=1");
  TORCH_CHECK(output_padding == 0, "custom CUTE kernel currently supports output_padding=0");
  TORCH_CHECK(weight.size(2) == 3 && weight.size(3) == 3 && weight.size(4) == 3,
              "custom CUTE kernel is specialized for kernel_size=3");

  const int64_t N = x.size(0);
  const int64_t C = x.size(1);
  const int64_t Din = x.size(2);
  const int64_t Hin = x.size(3);
  const int64_t Win = x.size(4);

  const int64_t OC = weight.size(1);
  TORCH_CHECK(weight.size(0) == C, "weight.size(0) must equal in_channels for groups=1");
  if (bias.has_value()) {
    TORCH_CHECK(bias.value().dim() == 1 && bias.value().size(0) == OC, "bias must be [out_channels]");
  }

  const int64_t Dout = (Din - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  const int64_t Hout = (Hin - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  const int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (3 - 1) + output_padding + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed-convolution output size");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Dout, Hout, Wout}, x.options());

  constexpr int TILE_Z = 4;
  constexpr int TILE_Y = 4;
  constexpr int TILE_X = 16;
  const int64_t tiles_d = (Dout + TILE_Z - 1) / TILE_Z;
  const int64_t tiles_h = (Hout + TILE_Y - 1) / TILE_Y;
  const int64_t tiles_w = (Wout + TILE_X - 1) / TILE_X;
  const int64_t spatial_tiles = tiles_d * tiles_h * tiles_w;
  const int64_t co_tiles = (OC + 24 - 1) / 24;

  dim3 block(256);
  dim3 grid((unsigned)spatial_tiles, (unsigned)co_tiles, (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  convt3d_s1_kernel<float, 3><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)Din, (int)Hin, (int)Win,
      (int)OC, (int)Dout, (int)Hout, (int)Wout,
      (int)padding);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convt3d_s1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

convt3d_ext = load_inline(
    name="convt3d_cute_s1_k3_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with one custom CUTE/CUDA kernel.

    The custom path is specialized for the provided configuration family:
    square 3x3x3 kernel, groups=1, stride=1, dilation=1, output_padding=0.
    Parameters are kept in an nn.ConvTranspose3d submodule so initialization and
    state_dict layout match the reference module, while forward() executes only
    the handwritten CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self.use_bias = bool(bias)

        self.conv_transpose3d = nn.ConvTranspose3d(
            self.in_channels,
            self.out_channels,
            (self.kernel_size, self.kernel_size, self.kernel_size),
            stride=self.stride,
            padding=self.padding,
            output_padding=self.output_padding,
            dilation=self.dilation,
            groups=self.groups,
            bias=self.use_bias,
        )
        self._ext = convt3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_cute_forward(
            x,
